sn_aia_tool.script:
(function(inputs) {
    var T = 'x_snc_ptag_engage_engagement_request';
    var gr = new GlideRecord(T);
    if (!inputs || !inputs.request_sys_id || !gr.get(inputs.request_sys_id)) {
        return JSON.stringify({ok: false, error: 'record not found'});
    }
    var txt = ('' + (inputs.draft_text || '')).trim();
    txt = txt.replace(/^\s*\[AI Triage Draft\]\s*/i, '');
    if (!txt) return JSON.stringify({ok: false, error: 'empty draft'});
    /* JOURNAL-ONLY BY CONSTRUCTION: the only assignment is the work_notes
       journal field. No state, assignment, scoring or any other field. */
    gr.work_notes = '[AI Triage Draft] ' + txt;
    gr.update();
    return JSON.stringify({ok: true, number: gr.getValue('number')});
})(inputs);
